// Authorization checks
{
  const mk = () => new DocumentRepository([
    { id: 'own', tenant: 'a', owner: 'e', deleted: false, archived: false },
    { id: 'other', tenant: 'a', owner: 'x', deleted: false, archived: false },
    { id: 'gone', tenant: 'a', owner: 'e', deleted: true, archived: false },
    { id: 'foreign', tenant: 'b', owner: 'e', deleted: false, archived: false },
    { id: 'done', tenant: 'a', owner: 'x', deleted: false, archived: true },
  ]);
  const r = mk(); const s = new DocumentService(r);
  const snap = () => JSON.stringify([r.documents, r.audit]);
  const actor = (role, user = 'e', tenant = 'a') => ({ tenant, user, role });
  const fails = (a, id, msg) => { const before = snap(); assert.throws(() => s.archive(a, id), new RegExp('^Error: ' + msg + '$')); assert.equal(snap(), before); };
  for (const id of ['missing', 'gone', 'foreign']) { fails(actor('admin'), id, 'not found'); fails(actor('viewer'), id, 'not found'); }
  fails(actor('viewer'), 'own', 'forbidden');
  fails(actor('editor'), 'other', 'forbidden');
  fails(actor('viewer', 'x'), 'done', 'forbidden');
  fails(actor('editor', 'e'), 'done', 'forbidden');
  s.archive(actor('editor'), 'own');
  assert.deepEqual(r.audit, [{ actor: 'e', document: 'own' }]);
  s.archive(actor('editor'), 'own');
  assert.equal(r.audit.length, 1);
  s.archive(actor('admin', 'adm'), 'other');
  assert.equal(r.documents[1].archived, true);
  assert.deepEqual(r.audit[1], { actor: 'adm', document: 'other' });
  s.archive(actor('admin', 'adm'), 'done');
  assert.equal(r.audit.length, 2);
}

